import { Component } from '@angular/core';
import { CoreIcon, ICON_TEMPLATE } from '@primeicons/angular/core';
import { image } from '@primeicons/core/image';

@Component({
    selector: 'svg[data-p-icon="image"]',
    standalone: true,
    template: ICON_TEMPLATE
})
export class Image extends CoreIcon {
    constructor() {
        super();
        this._icon = image;
    }
}
